import { Controller, Get, Patch, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const ROLE = '인사 담당자';
const STATUSES = ['작성중', '작성완료'];
const DATE_PATTERN = /^\d{4}-\d{2}-\d{2}$/;

function textOf(value: unknown): string {
  if (value === null || value === undefined) {
    return '';
  }
  return String(value).trim();
}

@Controller('api/v1')
export class FnSfr02202Controller {
  @Post('/social-insurance-reports')
  @HttpCode(200)
  async createSocialInsuranceReport(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    const enrollmentId = textOf(data['socialInsuranceEnrollmentId']);
    const reportType = textOf(data['reportType']);
    const baseDate = textOf(data['baseDate']);
    const formContent = textOf(data['formContent']);
    if (!enrollmentId || !reportType || !baseDate) {
      throw new ApiError(422, 'REPORT_REQUIRED_FIELD_MISSING', '필수 기재 항목이 누락되었습니다. 대상자, 신고서 종류, 신고 기준일을 입력하세요.');
    }
    if (!/^\d+$/.test(enrollmentId)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '대상자 형식이 올바르지 않습니다.');
    }
    if (reportType.length > 50) {
      throw new ApiError(400, 'VALIDATION_FAILED', '신고서 종류는 50자 이내로 입력하세요.');
    }
    if (!DATE_PATTERN.test(baseDate)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '신고 기준일은 YYYY-MM-DD 형식으로 입력하세요.');
    }
    return transaction(async (db) => {
      const found = await db.query(
        'SELECT social_insurance_enrollment_id AS "id" FROM social_insurance_enrollment WHERE social_insurance_enrollment_id = CAST(:enrollmentId AS bigint)',
        { enrollmentId },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'ENROLLMENT_NOT_FOUND', '신고 대상자가 등록되지 않았습니다. 대상자를 먼저 등록하세요.');
      }
      // 가정: 신규 신고서의 처리 상태는 '작성중'으로 시작한다.
      const rows = await db.query(
        `INSERT INTO social_insurance_report
           (social_insurance_enrollment_id, report_type, base_date, status, form_content, created_at, updated_at)
         VALUES
           (CAST(:enrollmentId AS bigint), :reportType, CAST(:baseDate AS date), '작성중', :formContent, now(), now())
         RETURNING social_insurance_report_id AS "socialInsuranceReportId", status AS "status"`,
        { enrollmentId, reportType, baseDate, formContent: formContent === '' ? null : formContent },
      );
      return rows[0];
    });
  }

  @Get('/social-insurance-reports')
  async listSocialInsuranceReports(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const query = checks.queryOf(req.query);
    const pageText = textOf(query['page']) || '0';
    const sizeText = textOf(query['size']) || '20';
    if (!/^\d+$/.test(pageText) || !/^\d+$/.test(sizeText)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호와 크기는 숫자로 입력하세요.');
    }
    const page = Number(pageText);
    const size = Math.min(Math.max(Number(sizeText), 1), 200);
    const reportType = textOf(query['reportType']);
    const status = textOf(query['status']);
    const baseDate = textOf(query['baseDate']);
    if (status !== '' && !STATUSES.includes(status)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '처리 상태가 올바르지 않습니다.');
    }
    if (baseDate !== '' && !DATE_PATTERN.test(baseDate)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '신고 기준일은 YYYY-MM-DD 형식으로 입력하세요.');
    }
    const where = `WHERE (CAST(:reportType AS text) IS NULL OR report_type = CAST(:reportType AS text))
        AND (CAST(:status AS text) IS NULL OR status = CAST(:status AS text))
        AND (CAST(:baseDate AS text) IS NULL OR base_date = CAST(:baseDate AS date))`;
    const filters = {
      reportType: reportType === '' ? null : reportType,
      status: status === '' ? null : status,
      baseDate: baseDate === '' ? null : baseDate,
    };
    return transaction(async (db) => {
      const counted = await db.query(
        `SELECT COUNT(*) AS "total" FROM social_insurance_report ${where}`,
        filters,
      );
      const items = await db.query(
        `SELECT social_insurance_report_id AS "socialInsuranceReportId",
                social_insurance_enrollment_id AS "socialInsuranceEnrollmentId",
                report_type AS "reportType",
                to_char(base_date, 'YYYY-MM-DD') AS "baseDate",
                status AS "status",
                form_content AS "formContent"
           FROM social_insurance_report
           ${where}
          ORDER BY social_insurance_report_id DESC
          LIMIT CAST(:size AS bigint) OFFSET CAST(:offset AS bigint)`,
        { ...filters, size, offset: page * size },
      );
      return { items, page, size, total: Number(counted[0]['total']) };
    });
  }

  @Patch('/social-insurance-reports/:socialInsuranceReportId')
  @HttpCode(200)
  async updateSocialInsuranceReport(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const reportId = req.params['socialInsuranceReportId'];
    const data = checks.inputOf(req.body);
    const hasBaseDate = data['baseDate'] !== undefined && data['baseDate'] !== null;
    const hasContent = data['formContent'] !== undefined && data['formContent'] !== null;
    const baseDate = textOf(data['baseDate']);
    const formContent = textOf(data['formContent']);
    if (!/^\d+$/.test(reportId)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '신고서 ID 형식이 올바르지 않습니다.');
    }
    if (!hasBaseDate && !hasContent) {
      throw new ApiError(422, 'REPORT_REQUIRED_FIELD_MISSING', '수정할 기재 항목이 없습니다.');
    }
    if (hasBaseDate && baseDate === '') {
      throw new ApiError(422, 'REPORT_REQUIRED_FIELD_MISSING', '신고 기준일은 비울 수 없습니다.');
    }
    if (hasBaseDate && !DATE_PATTERN.test(baseDate)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '신고 기준일은 YYYY-MM-DD 형식으로 입력하세요.');
    }
    return transaction(async (db) => {
      const found = await db.query(
        'SELECT status AS "status" FROM social_insurance_report WHERE social_insurance_report_id = CAST(:reportId AS bigint)',
        { reportId },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'REPORT_NOT_FOUND', '신고서를 찾을 수 없습니다.');
      }
      // 작성완료 후 수정은 상태 변경 후에만 가능하다. 이 API에는 상태 변경이 없으므로 거절한다.
      if (found[0]['status'] === '작성완료') {
        throw new ApiError(409, 'REPORT_COMPLETED', '작성완료된 신고서는 상태를 변경한 뒤에만 수정할 수 있습니다.');
      }
      await db.execute(
        `UPDATE social_insurance_report
            SET base_date = COALESCE(CAST(:baseDate AS date), base_date),
                form_content = CASE WHEN :hasContent THEN CAST(:formContent AS text) ELSE form_content END,
                updated_at = now()
          WHERE social_insurance_report_id = CAST(:reportId AS bigint)`,
        {
          reportId,
          baseDate: hasBaseDate ? baseDate : null,
          hasContent,
          formContent: hasContent ? formContent : null,
        },
      );
      return { socialInsuranceReportId: Number(reportId) };
    });
  }
}

