import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  DateText,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Pairs,
  Tiles,
  Form,
  Field,
  TextInput,
  DateInput,
  Select,
  LookupSelect,
  RefName,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

const SIZE = 20;
const STATUS_OPTIONS: [string, string][] = [
  ['작성중', '작성중'],
  ['작성완료', '작성완료'],
];

export default function FnSfr02202Page({ role, notify }: PageProps) {
  const [reportType, setReportType] = useState('');
  const [status, setStatus] = useState('');
  const [baseDate, setBaseDate] = useState('');
  const [applied, setApplied] = useState<Row>({});
  const [page, setPage] = useState(0);
  const [detail, setDetail] = useState<Row | null>(null);
  const [creating, setCreating] = useState(false);
  const [editing, setEditing] = useState<Row | null>(null);

  const [newEnrollment, setNewEnrollment] = useState<number | string>('');
  const [newType, setNewType] = useState('');
  const [newBaseDate, setNewBaseDate] = useState('');
  const [newContent, setNewContent] = useState('');

  const [editBaseDate, setEditBaseDate] = useState('');
  const [editContent, setEditContent] = useState('');

  const list = useData<Page>(
    () => call<Page>('GET', '/social-insurance-reports', role, undefined, { ...applied, page, size: SIZE }),
    [role, applied, page],
  );
  const rows = list.data?.items ?? [];
  const inProgress = rows.filter((r) => r['status'] === '작성중').length;

  function search() {
    setPage(0);
    setApplied({ reportType, status, baseDate });
  }

  function reset() {
    setReportType('');
    setStatus('');
    setBaseDate('');
    setPage(0);
    setApplied({});
  }

  function openCreate() {
    setNewEnrollment('');
    setNewType('');
    setNewBaseDate('');
    setNewContent('');
    setCreating(true);
  }

  function openEdit(row: Row) {
    setEditBaseDate(String(row['baseDate'] ?? ''));
    setEditContent(String(row['formContent'] ?? ''));
    setDetail(null);
    setEditing(row);
  }

  async function submitCreate() {
    if (newEnrollment === '' || !newType.trim() || !newBaseDate) {
      throw new Error('대상자, 신고서 종류, 신고 기준일을 모두 입력하세요.');
    }
    await call('POST', '/social-insurance-reports', role, {
      socialInsuranceEnrollmentId: newEnrollment,
      reportType: newType.trim(),
      baseDate: newBaseDate,
      formContent: newContent,
    });
    notify('사회보험 신고서를 저장했습니다.');
    setCreating(false);
    list.reload();
  }

  async function submitEdit() {
    if (!editing) {
      return;
    }
    if (!editBaseDate) {
      throw new Error('신고 기준일을 입력하세요.');
    }
    await call('PATCH', `/social-insurance-reports/${editing['socialInsuranceReportId']}`, role, {
      baseDate: editBaseDate,
      formContent: editContent,
    });
    notify('신고서 기재 항목을 수정했습니다.');
    setEditing(null);
    list.reload();
  }

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>신고서 현황</h2>
        <Tiles
          items={[
            ['전체 신고서', list.data?.total ?? 0],
            ['현재 쪽 작성중', inProgress],
            ['현재 쪽 작성완료', rows.length - inProgress],
          ]}
        />
      </section>
      <section className="box span-12">
        <h2>신고서 목록</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="신고서 종류">
            <TextInput value={reportType} onChange={setReportType} />
          </Field>
          <Field label="처리 상태">
            <Select value={status} onChange={setStatus} options={STATUS_OPTIONS} placeholder="전체" />
          </Field>
          <Field label="신고 기준일">
            <DateInput value={baseDate} onChange={setBaseDate} />
          </Field>
        </Filters>
        <Band total={list.data?.total}>
          <button type="button" onClick={openCreate}>신고서 작성</button>
        </Band>
        {list.error ? <ErrorText text={list.error} /> : null}
        <DataTable
          columns={[
            { key: 'socialInsuranceReportId', label: '사회보험 신고서 ID' },
            {
              key: 'socialInsuranceEnrollmentId',
              label: '대상자',
              render: (r) => (
                <RefName table="social_insurance_enrollment" role={role} value={r['socialInsuranceEnrollmentId']} />
              ),
            },
            { key: 'reportType', label: '신고서 종류' },
            { key: 'baseDate', label: '신고 기준일', render: (r) => <DateText value={r['baseDate']} /> },
            { key: 'status', label: '처리 상태', render: (r) => <Badge value={r['status']} /> },
            {
              key: 'actions',
              label: '처리',
              render: (r) =>
                r['status'] === '작성중' ? (
                  <button
                    type="button"
                    onClick={(e) => {
                      e.stopPropagation();
                      openEdit(r);
                    }}
                  >
                    수정
                  </button>
                ) : null,
            },
          ]}
          rows={rows}
          onRowClick={(r) => setDetail(r)}
          empty="등록된 신고서가 없습니다."
        />
        <Pager page={page} size={SIZE} total={list.data?.total ?? 0} onPage={setPage} />
      </section>

      {detail ? (
        <Drawer title="신고서 상세" onClose={() => setDetail(null)}>
          <Pairs
            items={[
              ['사회보험 신고서 ID', String(detail['socialInsuranceReportId'])],
              [
                '대상자',
                <RefName table="social_insurance_enrollment" role={role} value={detail['socialInsuranceEnrollmentId']} />,
              ],
              ['신고서 종류', String(detail['reportType'] ?? '')],
              ['신고 기준일', <DateText value={detail['baseDate']} />],
              ['처리 상태', <Badge value={detail['status']} />],
              ['신고서 기재 항목', String(detail['formContent'] ?? '')],
            ]}
          />
          {detail['status'] === '작성중' ? (
            <button type="button" onClick={() => openEdit(detail)}>수정</button>
          ) : null}
        </Drawer>
      ) : null}

      {creating ? (
        <Drawer title="신고서 작성" onClose={() => setCreating(false)}>
          <Form onSubmit={submitCreate} submit="저장">
            <Field label="대상자" required>
              <LookupSelect
                table="social_insurance_enrollment"
                role={role}
                value={newEnrollment}
                onChange={setNewEnrollment}
              />
            </Field>
            <Field label="신고서 종류" required>
              <TextInput value={newType} onChange={setNewType} />
            </Field>
            <Field label="신고 기준일" required>
              <DateInput value={newBaseDate} onChange={setNewBaseDate} />
            </Field>
            <Field label="신고서 기재 항목" wide>
              <TextInput value={newContent} onChange={setNewContent} multiline />
            </Field>
          </Form>
        </Drawer>
      ) : null}

      {editing ? (
        <Drawer title="신고서 수정" onClose={() => setEditing(null)}>
          <Form onSubmit={submitEdit} submit="수정 저장">
            <Field label="신고 기준일" required>
              <DateInput value={editBaseDate} onChange={setEditBaseDate} />
            </Field>
            <Field label="신고서 기재 항목" wide>
              <TextInput value={editContent} onChange={setEditContent} multiline />
            </Field>
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
